args.command:
cd /tmp && cat > hyp.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
void fmt(double x, char*out){
  if (isnan(x)) { sprintf(out, "%g", x); return; }
  if (isinf(x)) { sprintf(out, x<0?"-inf":"inf"); return; }
  char s[64];
  for(int p=1;p<=15;p++){
    sprintf(s,"%.*g",p,x);
    if(strtod(s,0)==x){ goto done; }
  }
  sprintf(s,"%.17g",x);
done:
  if(!strpbrk(s,".eEnNiI")) strcat(s,".0");
  strcpy(out,s);
}
int main(int argc,char**argv){
  char line[128];
  while(fgets(line,sizeof line,stdin)){
    double x=strtod(line,0); // hex float input
    char b[64]; fmt(x,b);
    printf("%s\n",b);
  }
}
EOF
gcc -O2 -o hyp hyp.c -lm
./hyp < hexes.txt > hyp_out.txt
diff lua_fuzz_out.txt hyp_out.txt | head -20
diff -q lua_fuzz_out.txt hyp_out.txt && echo PERFECT_MATCH

