args.command:
cd /tmp && cat > hyp2.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
void fmt(double x, char*out){
  char s[64];
  sprintf(s,"%.15g",x);
  if (strtod(s,0)!=x && !isnan(x)) sprintf(s,"%.17g",x);
  if (isfinite(x) && !strpbrk(s,".eE")) strcat(s,".0");
  strcpy(out,s);
}
int main(){
  char line[128];
  while(fgets(line,sizeof line,stdin)){
    double x=strtod(line,0);
    char b[64]; fmt(x,b);
    printf("%s\n",b);
  }
}
EOF
gcc -O2 -o hyp2 hyp2.c -lm
./hyp2 < hexes.txt > hyp2_out.txt
diff lua_fuzz_out.txt hyp2_out.txt && echo PERFECT_MATCH
# bigger fuzz
python3 - << 'EOF'
import random, struct
random.seed(1234)
with open('hexes2.txt','w') as f:
    n=0
    while n<5000:
        b=random.getrandbits(64)
        x=struct.unpack('<d',struct.pack('<Q',b))[0]
        if x!=x or abs(x)==float('inf'): continue
        f.write(x.hex()+'\n'); n+=1
    for _ in range(2000):
        f.write((random.randint(0,10**17)+0.0).hex()+'\n')
        f.write((random.uniform(-1e6,1e6)).hex()+'\n')
EOF
paste -sd, hexes2.txt | wc -c

